let parsed;
try {
  parsed = JSON.parse($json.message?.content ?? '{}');
} catch (e) {
  parsed = {};
}
const file = (parsed.file ?? '').trim().replace(/^\.\//, '').replace(/^[ab]\//, '');
let hunk = parsed.diff ?? '';

// Strip a stray reasoning-mode control token (e.g. "/think", a Qwen
// chat-template artifact observed leaking into content on a real run).
hunk = hunk
  .split('\n')
  .filter((l) => !/^\s*\/(no_)?think\s*$/.test(l))
  .join('\n');

// The model may include header lines anyway despite being told the diff
// field is hunk-only - if so, discard everything before the first real
// hunk header rather than trying to parse whatever header it invented.
// If there's no "@@ " header at all (observed directly: the model wrote
// only "+" content lines, no header), there's nothing safely applicable -
// treat it as empty rather than pass through content patch can't anchor
// (it happened to no-op harmlessly via its own leniency when this was
// observed, but that's not guaranteed, so don't rely on it).
{
  const atMatch = hunk.match(/^@@ /m);
  if (atMatch) {
    hunk = hunk.slice(atMatch.index);
  } else {
    hunk = '';
  }
}

// If the model repeated itself (a second @@ header appears), keep only
// the first hunk - one file, one hunk is this pipeline's scope for now.
{
  const secondAt = hunk.indexOf('\n@@ ', 1);
  if (secondAt !== -1) {
    hunk = hunk.slice(0, secondAt);
  }
}

// Context lines (unchanged lines) inside the hunk need a leading space
// marker - a real, observed model omission even with a byte-verified-
// correct worked example in the prompt.
{
  const lines = hunk.split('\n');
  for (let i = 1; i < lines.length; i++) {
    if (lines[i].length > 0 && !/^[ +-]/.test(lines[i])) {
      lines[i] = ' ' + lines[i];
    }
  }
  hunk = lines.join('\n');
}

// Recompute the @@ header's COUNTS from what's actually in the hunk body,
// trusting only the start line numbers - a real, observed, seemingly
// universal LLM diff weak point (miscounting the old/new line totals by
// one even when every individual line is otherwise well-formed, which
// `patch` rejects outright as malformed).
{
  const lines = hunk.split('\n');
  const headerMatch = lines[0]?.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)$/);
  if (headerMatch) {
    const oldStart = headerMatch[1];
    const newStart = headerMatch[2];
    const rest = headerMatch[3] || '';
    const body = lines.slice(1);
    // A trailing '' element from split('\n') means the hunk ended with a
    // real newline - that's not a line of content, just an artifact of
    // splitting, and must NOT be counted (real bug found and fixed here:
    // it was falling into the "context line" branch below and inflating
    // BOTH counts by one, corrupting an already-correct header from 3,3
    // to 4,4 on a real run - actively breaking output that started right).
    const countable = body.length > 0 && body[body.length - 1] === '' ? body.slice(0, -1) : body;
    let oldCount = 0;
    let newCount = 0;
    for (const bl of countable) {
      if (bl.startsWith('-')) oldCount++;
      else if (bl.startsWith('+')) newCount++;
      else {
        oldCount++;
        newCount++;
      }
    }
    lines[0] = '@@ -' + oldStart + ',' + oldCount + ' +' + newStart + ',' + newCount + ' @@' + rest;
    hunk = lines.join('\n');
  }
}

if (hunk.length > 0 && !hunk.endsWith('\n')) {
  hunk = hunk + '\n';
}
const diff = (file && hunk) ? ('--- a/' + file + '\n+++ b/' + file + '\n' + hunk) : '';
return [{ json: { diff } }];

