const fileContextText = $('Fetch File Context').item.json.stdout ?? '';
let existingLines = null;
if (file) {
  let markerIdx = fileContextText.indexOf('=== ' + file + ' ===');
  let markerLen = ('=== ' + file + ' ===').length;
  if (markerIdx === -1) {
    markerIdx = fileContextText.indexOf('=== ./' + file + ' ===');
    markerLen = ('=== ./' + file + ' ===').length;
  }
  if (markerIdx !== -1) {
    const afterMarker = fileContextText.slice(markerIdx + markerLen + 1);
    const nextMarkerIdx = afterMarker.indexOf('\n=== ');
    const existingContent = (nextMarkerIdx === -1 ? afterMarker : afterMarker.slice(0, nextMarkerIdx)).replace(/\n$/, '');
